grid=[[0,0,0,6,0,0,0,5],[9,0,0,0,6,0,0,0],[0,9,0,0,0,6,0,0],[0,0,9,0,0,0,6,0],[3,0,0,9,0,0,0,6],[1,3,0,0,9,0,0,0],[0,1,3,0,0,9,0,0],[0,0,1,3,0,0,9,0]]
for p in range(1,9):
    ok=True
    for c in range(8):
        vals={}
        for r in range(8):
            if grid[r][c]:
                k=r%p
                if k in vals and vals[k]!=grid[r][c]: ok=False
                vals[k]=grid[r][c]
    if ok:
        print('min p',p)
        out=[]
        for r in range(8):
            row=[]
            for c in range(8):
                vals={}
                for rr in range(8):
                    if grid[rr][c]: vals[rr%p]=grid[rr][c]
                row.append(grid[r][c] or vals.get(r%p,0))
            out.append(row)
        print(out)
        break

